import{_ as t,o as a,c as o,a7 as s}from"./chunks/framework.FWlv_suP.js";const h=JSON.parse('{"title":"Vault Nest Data Collection","description":"Standalone summary of Vault Nest data practices.","frontmatter":{"title":"Vault Nest Data Collection","description":"Standalone summary of Vault Nest data practices.","navbar":false,"sidebar":false,"aside":false,"outline":false,"footer":false,"prev":false,"next":false,"editLink":false,"lastUpdated":false,"pageClass":"standalone-policy"},"headers":[],"relativePath":"data-collection/vault-nest.md","filePath":"data-collection/vault-nest.md"}'),i={name:"data-collection/vault-nest.md"};function r(n,e,l,c,d,p){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="vault-nest-data-collection" tabindex="-1">Vault Nest Data Collection <a class="header-anchor" href="#vault-nest-data-collection" aria-label="Permalink to &quot;Vault Nest Data Collection&quot;">​</a></h1><p><strong>Last reviewed:</strong> August 1, 2026</p><h2 id="data-stored-locally" tabindex="-1">Data stored locally <a class="header-anchor" href="#data-stored-locally" aria-label="Permalink to &quot;Data stored locally&quot;">​</a></h2><p>Vault Nest stores the credentials, secure notes, identities, Wi-Fi information, custom fields, labels, saved templates, preferences, and security settings you provide. Sensitive vault-item contents are encrypted locally. Limited indexed metadata, such as item type, status, expiry dates, and timestamps, remains outside each encrypted payload.</p><p>Optional features may also store Android-Keystore-protected biometric unlock material, encrypted intrusion-evidence photos, temporary encrypted notification copy values, and notification schedules on the device.</p><h2 id="data-collected-by-the-developer" tabindex="-1">Data collected by the developer <a class="header-anchor" href="#data-collected-by-the-developer" aria-label="Permalink to &quot;Data collected by the developer&quot;">​</a></h2><p>The app has no account, developer cloud, analytics, advertising, crash reporting, or tracking service. The developer does not receive vault contents, keys, passwords, evidence images, preferences, or app-usage data.</p><p>If you email support, the developer receives the information you voluntarily include in that message.</p><h2 id="data-sent-to-other-services-by-your-actions" tabindex="-1">Data sent to other services by your actions <a class="header-anchor" href="#data-sent-to-other-services-by-your-actions" aria-label="Permalink to &quot;Data sent to other services by your actions&quot;">​</a></h2><ul><li>Optional website-icon retrieval requests the website address stored in an item and candidate image URLs. Website servers may receive the device IP address, requested URL, time, and user agent. Vault secrets are not included.</li><li>Android receives notification content needed for optional expiry reminders.</li><li>Copy and share actions place selected information into the system clipboard or pass it to an app you choose.</li><li>A document or cloud provider you select can receive exported backup or CSV files.</li></ul><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><p>Camera, notifications, biometrics, internet access, and selected-file access are used only for their related features. Vault Nest does not require broad storage, location, contacts, phone, or SMS access for the reviewed functionality.</p><h2 id="contact" tabindex="-1">Contact <a class="header-anchor" href="#contact" aria-label="Permalink to &quot;Contact&quot;">​</a></h2><p>Questions about these practices can be sent to <strong><a href="mailto:anand.official.in@gmail.com" target="_blank" rel="noreferrer">anand.official.in@gmail.com</a></strong>.</p>',14)])])}const m=t(i,[["render",r]]);export{h as __pageData,m as default};
